\includegraphics[width=\textwidth]{fig1_selection.pdf}
\caption{Screening and final analysis flow for January 2022--August 2026, with one exact-version record per paper. Detailed reasons for non-retention and the complete count breakdown are reported in Appendix~\ref{app:availability}. Box sizes do not encode counts.}\label{fig:flow}
\end{figure}

\begin{table}[htbp]\centering
\caption{Included records by first-submission year. The incomplete 2026 year is not directly compared with full earlier years as an annual growth rate.}\label{tab:years}
\begin{tabular}{lrr}\toprule
Year & Observed months & Included records\\\midrule
2022 & January--December &160\\
2023 & January--December &861\\
2024 & January--December &2,735\\
2025 & January--December &5,277\\
